 * @method
 * @name scwin.self_close
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.self_close = async function () {
    /* sdd-asis-lifecycle:begin self_close — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (await $c.win.confirm("신청을 취소하시겠습니까?")) {
        $c.win.closePopup();
    }
    /* sdd-asis-lifecycle:end */
};
